code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    board = [row[:] for row in grid]
    wall_top = all(v == 2 for v in grid[0])
    wall_bottom = all(v == 2 for v in grid[-1])
    if wall_top:
        direction = -1
        wall_rows = {0}
    elif wall_bottom:
        direction = 1
        wall_rows = {h - 1}
    else:
        raise ValueError("expected a full horizontal 2-wall")

    unseen = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != 0 and grid[r][c] != 2}
    components = []
    while unseen:
        start = unseen.pop()
        color = grid[start[0]][start[1]]
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                p = (nr, nc)
                if p in unseen and grid[nr][nc] == color:
                    unseen.remove(p)
                    comp.add(p)
                    stack.append(p)
        components.append(comp)

    if direction == -1:
        components.sort(key=lambda comp: min(r for r, c in comp))
    else:
        components.sort(key=lambda comp: max(r for r, c in comp), reverse=True)

    occupied = { (r,c) for r in wall_rows for c in range(w) }
    result = [[0] * w for _ in range(h)]
    for r, c in occupied:
        result[r][c] = 2
    for comp in components:
        color = grid[next(iter(comp))[0]][next(iter(comp))[1]]
        shift = 0
        while True:
            nxt = {(r + direction * (shift + 1), c) for r, c in comp}
            if any(r < 0 or r >= h or (r,c) in occupied for r,c in nxt):
                break
            shift += 1
        for r, c in comp:
            nr = r + direction * shift
            result[nr][c] = color
            occupied.add((nr,c))
    return result
'''
